/* =====================================================================
   Self-test — isolated Sim instances exercising the real systems.
   ===================================================================== */
function runSelfTest(){
  const tests = [];
  const T = (name, fn) => {
    try { tests.push({ name, passed: true, detail: fn() || 'ok' }); }
    catch (e) { tests.push({ name, passed: false, detail: String(e && e.message || e) }); }
  };
  const snapJSON = s => JSON.stringify(s.snapshot());
  const drain = s => { s.events.length = 0; };

  const runDemo = (seed, maxMs) => {
    const s = new Sim(seed); s.setDemo(true);
    const phases = new Set([1]);
    for (let t = 0; t < maxMs && !s.outcome; t += TICK){
      s.step(TICK); phases.add(s.phase); drain(s);
    }
    return { sim: s, phases };
  };

  const demo = runDemo(4242, 100000);

  T('deterministic reset', () => {
    const a = new Sim(1234); a.setDemo(true); a.step(30000); drain(a);
    const b = new Sim(999); b.step(5000); b.reset(1234); b.setDemo(true); b.step(30000); drain(b);
    if (snapJSON(a) !== snapJSON(b)) throw new Error('same seed + same inputs diverged');
    return 'identical snapshots after 30 s';
  });

  T('pause stops simulation time', () => {
    const s = new Sim(7); s.step(3000);
    const t0 = s.t;
    s.paused = true; s.step(2000);
    if (s.t !== t0) throw new Error('time advanced while paused');
    s.paused = false; s.step(160);
    if (s.t <= t0) throw new Error('time did not resume');
    return 'frozen while paused, resumes after';
  });

  T('phase progression', () => {
    if (!demo.phases.has(2) || !demo.phases.has(3)) throw new Error('phases seen: ' + [...demo.phases].join(','));
    return 'phases 1 → 2 → 3 reached';
  });

  T('success state reachable', () => {
    if (demo.sim.outcome !== 'victory') throw new Error('demo outcome: ' + demo.sim.outcome);
    if (demo.sim.t > 90000) throw new Error('run too long: ' + demo.sim.t);
    return 'victory at ' + (demo.sim.t / 1000).toFixed(1) + ' s';
  });

  T('failure state reachable', () => {
    const s = new Sim(4242);
    for (let t = 0; t < 60000 && !s.outcome; t += TICK){ s.step(TICK); drain(s); }
    if (s.outcome !== 'defeat') throw new Error('no-input outcome: ' + s.outcome);
    return 'defeat at ' + (s.t / 1000).toFixed(1) + ' s without input';
  });

  T('finite numeric state', () => {
    const bad = [];
    const walk = (o, p) => {
      if (typeof o === 'number'){ if (!Number.isFinite(o)) bad.push(p); }
      else if (Array.isArray(o)) o.forEach((v, i) => walk(v, p + '[' + i + ']'));
      else if (o && typeof o === 'object') for (const k in o) walk(o[k], p + '.' + k);
    };
    walk(demo.sim.snapshot(), 'win');
    const mid = new Sim(11); mid.setDemo(true); mid.step(20000); drain(mid);
    walk(mid.snapshot(), 'mid');
    if (bad.length) throw new Error('non-finite at ' + bad.join(', '));
    return 'all snapshot numbers finite';
  });

  T('instant restart restores initial state', () => {
    const fresh = new Sim(9);
    const s = new Sim(9); s.setDemo(true); s.step(25000); drain(s);
    s.reset(9); s.demo = false;
    if (snapJSON(s) !== snapJSON(fresh)) throw new Error('reset state differs from fresh state');
    s.step(4000); fresh.step(4000); drain(s); drain(fresh);
    if (snapJSON(s) !== snapJSON(fresh)) throw new Error('post-reset evolution differs');
    return 'reset ≡ fresh encounter';
  });

  T('demo uses the real gameplay systems', () => {
    const d = demo.sim;
    if (d.stats.parries < 8) throw new Error('demo barely interacted: ' + d.stats.parries + ' parries');
    const log = d.pressLog.slice();
    const r = new Sim(4242);           // no demo: replay the demo's press timings manually
    let i = 0;
    while (!r.outcome && r.t < d.t + 1000){
      if (i < log.length && log[i] === r.t + TICK){ r.press(); i++; }
      r.step(TICK); drain(r);
    }
    const a = d.snapshot(), b = r.snapshot();
    a.demo = b.demo = false;
    if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error('manual replay of demo inputs diverged');
    return 'demo inputs replayed manually → identical result (' + d.stats.parries + ' parries)';
  });

  return { passed: tests.every(t => t.passed), tests };
}

/* =====================================================================
   Renderer — sumi-e ink on parchment. Visual randomness uses its own
   seeded stream so gameplay determinism is never touched.
   ===================================================================== */
const cv = document.getElementById('cv');
const g = cv.getContext('2d');
