const PAL = {
  1: { paper:'#ede3cc', paper2:'#e0d1b2', ink:'#191521', ink2:'#2a2137', disc:'#e3a93f',
       accent:'#d8752b', eye:'#ffb545', mist:'rgba(25,21,33,0.05)' },
  2: { paper:'#e6d2ba', paper2:'#d3b898', ink:'#1b1420', ink2:'#331a2a', disc:'#c8444e',
       accent:'#c43b49', eye:'#ff5a63', mist:'rgba(50,20,32,0.06)' },

  _spawnEffect(kind, at, attack){
    const life = EFFECT_LIFE[kind] || 600;
    this._effectSeq++;
    this.effects.push({
      seq: this._effectSeq, kind, at, until: at+life,
      type: attack ? (attack.type || null) : null,
      angle: attack && attack.angle != null ? attack.angle : 0,
      attackId: attack && attack.id != null ? attack.id : null,
      phase: attack && attack.phase != null ? attack.phase : this.phase,
    });
  }

  snapshot(){
    return {
      time: this.time,
      seed: this.seed,
      phase: this.phase,
      phase2Start: this.phase2Start,
      phase3Start: this.phase3Start,
      encounterEnd: this.encounterEnd,
      started: this.started,
      paused: this.paused,
      demo: this.demo,
      outcome: this.outcome,
      score: this.score,
      combo: this.combo,
      bestCombo: this.bestCombo,
      player: {
        resolve: this.player.resolve,
        maxResolve: PLAYER_MAX_RESOLVE,
        cooldownRemaining: Math.max(0, PULSE_COOLDOWN - (this.time - this.lastPressTime)),
      },
      boss: {
        name: BOSS_NAME,
        stability: this.boss.stability,
        maxStability: this._maxStability,
      },
      attacks: this.attacks
        .filter(a => !a.resolved && this.time >= a.telegraphStart)
        .map(a => ({
          id: a.id, type: a.type, phase: a.phase, angle: a.angle,
          telegraphStart: a.telegraphStart, impactTime: a.impactTime,
          windowStart: a.windowStart, windowEnd: a.windowEnd,
          fizzleTime: a.fizzleTime,
        })),
      scheduleTotal: this.attacks.length,
      scheduleResolved: this.attacks.filter(a => a.resolved).length,
    };
  }

  runSelfTest(){
    const tests = [];
    const record = (name, fn) => {
      try{
        const ok = fn();
        tests.push({ name, passed: ok === true });
      }catch(err){
        tests.push({ name, passed:false, detail:String(err && err.message || err) });
      }
    };

    record('deterministic reset produces identical snapshots for the same seed', () => {
      const a = createGame(); a.reset(4242); a.start(); a.step(3333);
      const b = createGame(); b.reset(4242); b.start(); b.step(3333);
      return JSON.stringify(a.snapshot()) === JSON.stringify(b.snapshot());
    });

    record('pause halts simulation time', () => {
      const g = createGame(); g.reset(5); g.start(); g.step(1000);
      const t1 = g.snapshot().time;
      g.pause(); g.step(2000);
      const t2 = g.snapshot().time;
      g.resume(); g.step(500);
      const t3 = g.snapshot().time;
      return t1 === t2 && t3 > t2;
    });

    record('phase advances from I to III over the encounter', () => {
      const g = createGame(); g.reset(9); g.setDemo(true); g.start();
      const p1 = g.snapshot().phase;
      g.step(g.phase2Start + 200);
      const p2 = g.snapshot().phase;
      g.step((g.phase3Start - g.phase2Start) + 200);
      const p3 = g.snapshot().phase;
      return p1 === 1 && p2 === 2 && p3 === 3;
    });

    record('snapshot numeric fields stay finite', () => {
      const g = createGame(); g.reset(11); g.setDemo(true); g.start();
      for(let i=0;i<400;i++) g.step(50);
      const s = g.snapshot();
      const nums = [s.time, s.score, s.combo, s.bestCombo, s.player.resolve, s.player.cooldownRemaining, s.boss.stability, s.boss.maxStability];
      return nums.every(n => typeof n === 'number' && Number.isFinite(n));
    });

    record('demo autopilot reaches a success outcome', () => {
      const g = createGame(); g.reset(21); g.setDemo(true); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      return g.snapshot().outcome === 'success';
    });

    record('withholding input reaches a failure outcome', () => {
      const g = createGame(); g.reset(22); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      return g.snapshot().outcome === 'failure';
    });

    record('reset after an outcome restores a fresh run (instant restart)', () => {
      const g = createGame(); g.reset(23); g.start();
      let guard = 0;
      while(!g.snapshot().outcome && guard < 4000){ g.step(50); guard++; }
      g.reset(23);
      const s = g.snapshot();
      return s.time === 0 && s.outcome === null && s.phase === 1 && !s.started &&
        s.boss.stability === s.boss.maxStability && s.player.resolve === s.player.maxResolve;
    });

    record('demo mode drives the real gameplay state, not a canned animation', () => {
      const g = createGame(); g.reset(24); g.setDemo(true); g.start();
      const before = g.snapshot();
      for(let i=0;i<80;i++) g.step(50);
      const after = g.snapshot();
      const sameShape = Object.keys(before).every(k => k in after) &&
        Object.keys(before.boss).every(k => k in after.boss) &&
        Object.keys(before.player).every(k => k in after.player);
      return sameShape && after.time > before.time &&
        after.boss.stability < before.boss.stability && after.score > before.score;
    });

    const passed = tests.every(t => t.passed);
    return { passed, tests };
  }
}

function createGame(){ return new BossFightCore(); }

