+      live.paused = true;
+    } else {
+      live.reset(live.seed);
+      live.setDemo(true);
+    }
+    syncUi();
+  });
+  ui.mute.addEventListener("click", () => {
+    audio.muted = !audio.muted;
+    if (!audio.muted) audio.ensure();
+    else if (audio.ctx && audio.ctx.state === "running") audio.ctx.suspend();
+    syncUi();
+  });
+
+  canvas.addEventListener("pointerdown", (e) => {
+    if (e.button && e.button !== 0) return;
+    e.preventDefault();
+    onPress(e);
+  });
+
+  window.addEventListener("keydown", (e) => {
+    if (e.code === "Space" || e.key === " ") {
+      const tag = e.target && e.target.tagName;
+      if (tag === "BUTTON") return;
+      e.preventDefault();
+      if (!e.repeat) onPress(e);
+    } else if (e.key === "Escape" || e.key === "p" || e.key === "P") {
+      if (live.started && !live.outcome) {
+        live.paused = !live.paused;
+        syncUi();
+      }
+    }
+  });
+
+  window.addEventListener("resize", resize);
+  document.addEventListener("visibilitychange", () => {
+    if (document.hidden) {
+      if (live.started && !live.paused && !live.outcome) {
+        live.paused = true;
+        hiddenPause = true;
+      }
+    } else {
+      last = performance.now();
+      if (hiddenPause) {
+        live.paused = false;
+        hiddenPause = false;
+      }
+    }
+  });
+
+  window.__BOSS_FIGHT__ = {
+    reset: function (seed) { return live.reset(seed); },
+    start: function () { return live.start(); },
+    setDemo: function (enabled) { return live.setDemo(enabled); },
+    press: function () { return live.press(); },
+    step: function (ms) { return live.step(ms); },
+    snapshot: function () { return live.snapshot(); },
+    runSelfTest: runSelfTest
+  };
+
+  resize();
+  syncUi();
+  requestAnimationFrame(frame);
+})();
+  </script>
+</body>
+</html>

