const { spawn } = require('child_process');
const fs = require('fs');
const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const file = 'file:///Users/melvynx/Developer/agent-benchmarks/benchmarks/one-button-boss-fight/2026-08-13-cursor-agent-cursor-grok-4-6-high/index.html';
const port = 9229;
const chrome = spawn(chromePath, [
  '--headless=new',
  '--disable-gpu',
  `--remote-debugging-port=${port}`,
  '--window-size=1280,820',
  file
], { stdio: ['ignore', 'pipe', 'pipe'] });

function sleep(ms){ return new Promise(r => setTimeout(r, ms)); }

async function waitPort() {
  for (let i = 0; i < 40; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}/json`);
      if (res.ok) return await res.json();
    } catch (e) {}
    await sleep(150);
  }
  throw new Error('cdp not ready');
}

async function cdp(ws, id, method, params) {
  return new Promise((resolve, reject) => {
    const onmsg = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        ws.removeEventListener('message', onmsg);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    };
    ws.addEventListener('message', onmsg);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

(async () => {
  try {
    const targets = await waitPort();
    const page = targets.find(t => t.type === 'page') || targets[0];
    const ws = new WebSocket(page.webSocketDebuggerUrl);
    await new Promise((res, rej) => { ws.addEventListener('open', res); ws.addEventListener('error', rej); });
    await cdp(ws, 1, 'Runtime.enable', {});
    await sleep(400);
    const title = await cdp(ws, 2, 'Runtime.evaluate', { expression: 'document.title', returnByValue: true });
    const h1 = await cdp(ws, 3, 'Runtime.evaluate', { expression: 'document.querySelector("h1").textContent', returnByValue: true });
    const api = await cdp(ws, 4, 'Runtime.evaluate', { expression: 'typeof window.__BOSS_FIGHT__ + ":" + Object.keys(window.__BOSS_FIGHT__).sort().join(",")', returnByValue: true });
    const test = await cdp(ws, 5, 'Runtime.evaluate', { expression: 'JSON.stringify(window.__BOSS_FIGHT__.runSelfTest())', returnByValue: true, awaitPromise: true });
    await cdp(ws, 6, 'Runtime.evaluate', { expression: 'window.__BOSS_FIGHT__.reset(7); window.__BOSS_FIGHT__.setDemo(true); window.__BOSS_FIGHT__.step(2400); "ok"', returnByValue: true });
    await sleep(200);
    const shot = await cdp(ws, 7, 'Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync('/tmp/boss-fight-play.png', Buffer.from(shot.data, 'base64'));
    const snap = await cdp(ws, 8, 'Runtime.evaluate', { expression: 'JSON.stringify(window.__BOSS_FIGHT__.snapshot())', returnByValue: true });
    const errs = await cdp(ws, 9, 'Runtime.evaluate', { expression: 'window.__pageErrors ? window.__pageErrors : "none"', returnByValue: true });
    console.log(JSON.stringify({
      title: title.result.value,
      h1: h1.result.value,
      api: api.result.value,
      test: JSON.parse(test.result.value),
      snap: JSON.parse(snap.result.value),
      errs: errs.result.value
    }, null, 2));
    ws.close();
  } finally {
    chrome.kill('SIGTERM');
  }
})().catch((e) => { console.error(e); chrome.kill('SIGKILL'); process.exit(1); });
